import os
import boto3

def refresh_session(refresh_token: str) -> dict:
    """
    Refreshes an expired session or access token using AWS Cognito.

    Args:
        refresh_token: The refresh token to use for renewing the session.

    Returns:
        A dictionary containing the new access token, ID token, and refresh token.
        Raises an exception if the refresh fails.
    """
    client_id = os.environ.get("AWS_COGNITO_CLIENT_ID")
    if not client_id:
        raise ValueError("AWS_COGNITO_CLIENT_ID environment variable not set.")

    client = boto3.client("cognito-idp")

    try:
        response = client.initiate_auth(
            AuthFlow="REFRESH_TOKEN_AUTH",
            AuthParameters={
                "REFRESH_TOKEN": refresh_token
            },
            ClientId=client_id,
        )

        # The response structure might vary based on the Cognito setup.
        # This example assumes a common structure for access and ID tokens.
        new_tokens = {
            "AccessToken": response["AuthenticationResult"]["AccessToken"],
            "IdToken": response["AuthenticationResult"]["IdToken"],
        }
        if "RefreshToken" in response["AuthenticationResult"]:
            new_tokens["RefreshToken"] = response["AuthenticationResult"]["RefreshToken"]

        return new_tokens

    except client.exceptions.ClientError as e:
        raise RuntimeError(f"AWS Cognito error during token refresh: {e}")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

import os
import requests

def email_password_login(email: str, password: str):
    """
    Signs in a user with email and password using Firebase Authentication REST API
    and returns ID and refresh tokens.
    """
    firebase_api_key = os.environ.get("FIREBASE_API_KEY")
    if not firebase_api_key:
        raise ValueError("FIREBASE_API_KEY environment variable not set.")

    rest_api_endpoint = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={firebase_api_key}"

    headers = {"Content-Type": "application/json"}
    payload = {
        "email": email,
        "password": password,
        "returnSecureToken": True
    }

    try:
        response = requests.post(rest_api_endpoint, headers=headers, json=payload)
        response.raise_for_status()  # Raise an exception for HTTP errors
        data = response.json()
        return {
            "idToken": data.get("idToken"),
            "refreshToken": data.get("refreshToken"),
            "expiresIn": data.get("expiresIn"),
            "localId": data.get("localId")
        }
    except requests.exceptions.RequestException as e:
        error_message = f"Firebase authentication failed: {e}"
        if response.content:
            try:
                error_data = response.json()
                error_message += f" - {error_data.get('error', {}).get('message', 'Unknown error')}"
            except ValueError:
                error_message += f" - Raw response: {response.text}"
        raise RuntimeError(error_message)

import firebase_admin
from firebase_admin import credentials, auth
import os

def register_user(email, password):
    if not firebase_admin._apps:
        # Initialize Firebase Admin SDK if not already initialized
        # Replace 'path/to/your/serviceAccountKey.json' with the actual path to your Firebase service account key
        # or use an environment variable for security in production.
        # For example: os.environ.get("FIREBASE_SERVICE_ACCOUNT_KEY_PATH")
        cred = credentials.Certificate(os.environ.get("FIREBASE_SERVICE_ACCOUNT_KEY_PATH", "path/to/your/serviceAccountKey.json"))
        firebase_admin.initialize_app(cred)

    try:
        user = auth.create_user(
            email=email,
            password=password
        )
        return {"uid": user.uid, "email": user.email}
    except Exception as e:
        raise Exception(f"Failed to register user: {e}")
